    # If the item does not fit, assign the lowest possible priority.
    if remaining_capacity < item:
        return -float('inf')
    leftover = remaining_capacity - item          # non‑negative when feasible
    # Exponential penalty: higher priority for smaller leftover.
    return math.exp(-leftover)
