def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    leftover = remaining_capacity - item
    # Normalize leftover by bin capacity to keep the penalty scale consistent across instances
    if bin_capacity != 0.0:
        norm = leftover / bin_capacity
    else:
        norm = leftover
    # Quadratic penalty: more negative for larger slack, thus higher priority for tighter fit
    return -(norm * norm)
